func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestAddLargeValues(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "two large positives", a: 1_000_000_000, b: 1_000_000_000, want: 2_000_000_000},
		{name: "large positive plus large negative", a: 2_000_000_000, b: -1_000_000_000, want: 1_000_000_000},
		{name: "two large negatives", a: -1_000_000_000, b: -1_000_000_000, want: -2_000_000_000},
		{name: "max int32 plus zero", a: 2_147_483_647, b: 0, want: 2_147_483_647},
		{name: "min int32 plus one", a: -2_147_483_648, b: 1, want: -2_147_483_647},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := add(tt.a, tt.b); got != tt.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

